34	// (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE 
35	// OF THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.
36	//
37	//              https://opensource.org/license/bsd-3-clause
38	//--------------------------------------------------------------------------
39	// Description:
40	//   Egress IP Lookup module for WireGuard Data Plane.
41	//
42	//   Functionality:
43	//   1. Control Plane: Acts as a bridge between the CSR interface and the internal 
44	//      Routing Memory (`dpe_route_mem`). Handles address decoding/multiplexing
45	//      for writing and reading routing rules.
46	//
47	//   2. Data Plane: Parses incoming AXI Stream packets to extract the IPv4 
48	//      Destination Address. Uses a store-and-forward mechanism (beat buffer) 
49	//      to hold data while performing the routing table lookup.
50	//
51	//   3. Routing Action: Updates the outgoing AXI Stream sideband signals 
52	//      (tuser_dst, tid/peer_id) based on the lookup result, directing the 
53	//      packet to the correct physical port and associating it with a Peer.
54	//==========================================================================
55	
56	`timescale 1ns/1ps
57	
58	module dpe_egress_ip_lookup #(
59	  parameter int ENTRY_COUNT = 64,
60	  parameter bit USE_BYPASS_FROM_MEM = 1'b0
61	) (
62	  dpe_if.s_axis  s_axis,
63	  dpe_if.m_axis  m_axis,
64	
65	  input  csr_pkg::csr__dpe__routing_table__external__out_t hwif_out [ENTRY_COUNT], 
66	  output csr_pkg::csr__dpe__routing_table__external__in_t  hwif_in  [ENTRY_COUNT]
67	);
68	
69	  logic        req;
70	  logic        is_wr;
71	  logic [31:0] wr_data;
72	  logic [3:0]  addr_offset;
73	  logic [5:0]  mem_idx;
74	
75	  logic we_prefix, we_mask, we_peer, we_dst;
76	  logic [31:0] rdata_prefix, rdata_mask;
77	  logic [7:0]  rdata_peer;
78	  logic [2:0]  rdata_dst;
79	
80	  // -----------------------------------------------------------
81	  // INPUT MULTIPLEXER
82	  // -----------------------------------------------------------  
83	  always_comb begin
84	    req         = 1'b0;
85	    is_wr       = 1'b0;
86	    wr_data     = 32'd0;
87	    addr_offset = 4'd0;
88	    mem_idx     = 6'd0;
89	
90	    for (int i = 0; i < ENTRY_COUNT; i++) begin
91	       if (hwif_out[i].req) begin
92	          req         = 1'b1;
93	          is_wr       = hwif_out[i].req_is_wr;
94	          wr_data     = hwif_out[i].wr_data;
95	          addr_offset = hwif_out[i].addr; 
96	          mem_idx     = i[5:0];
97	       end
98	    end
99	  end
100	
101	  // -----------------------------------------------------------
102	  // OUTPUT DEMULTIPLEXER
103	  // -----------------------------------------------------------
104	  generate
105	    genvar k;
106	    for (k = 0; k < ENTRY_COUNT; k++) begin : GEN_RESP
107	       assign hwif_in[k].wr_ack = (mem_idx == k) ? (req && is_wr)  : 1'b0;
108	       assign hwif_in[k].rd_ack = (mem_idx == k) ? (req && !is_wr) : 1'b0;
109	       
110	       always_comb begin
111	          hwif_in[k].rd_data = 32'd0;
112	          if (mem_idx == k) begin
113	             case (addr_offset[3:2]) // Offset 0, 4, 8, C
114	                2'b00: hwif_in[k].rd_data = rdata_prefix;
115	                2'b01: hwif_in[k].rd_data = rdata_mask;
116	                2'b10: hwif_in[k].rd_data = {24'd0, rdata_peer};
117	                2'b11: hwif_in[k].rd_data = {29'd0, rdata_dst};
118	             endcase
119	          end
120	       end
121	    end
122	  endgenerate
123	
124	  // -----------------------------------------------------------
125	  // WRITING TO MEMORY
126	  // -----------------------------------------------------------
127	  always_comb begin
128	    we_prefix = 1'b0; we_mask = 1'b0; we_peer = 1'b0; we_dst = 1'b0;
129	    
130	    if (req && is_wr) begin
131	      case (addr_offset[3:2])
132	        2'b00: begin we_prefix = 1'b1; end
133	        2'b01: we_mask   = 1'b1;
134	        2'b10: we_peer   = 1'b1;
135	        2'b11: we_dst    = 1'b1;
136	      endcase
137	    end
138	  end
139	  
140	  logic        route_hit;
141	  logic [5:0]  route_idx;
142	  logic [2:0]  route_dst;
143	  logic [7:0]  route_peer;
144	  logic        route_bypass;
145	  logic [31:0] route_req_ip;
146	  logic        route_req_valid;
147	
148	  dpe_route_mem #(
149	    .ENTRY_COUNT(ENTRY_COUNT)
150	  ) u_mem (
151	    .clk        (s_axis.clk),
152	    .rst        (s_axis.rst),
153	
154	    .waddr      (mem_idx),
155	    .we_prefix  (we_prefix), .wdata_prefix(wr_data),
156	    .we_mask    (we_mask),   .wdata_mask (wr_data),
157	    .we_peer    (we_peer),   .wdata_peer (wr_data[7:0]),
158	    .we_dst     (we_dst),    .wdata_dst  (wr_data[2:0]),
159	
160	    .raddr      (mem_idx),
161	    .rdata_prefix(rdata_prefix), .rdata_mask(rdata_mask),
162	    .rdata_peer(rdata_peer),     .rdata_dst(rdata_dst),
163	
164	    .req_ip     (route_req_ip),
165	    .req_valid  (route_req_valid),
166	    .resp_hit   (route_hit),
167	    .resp_route_idx(route_idx),
168	    .resp_dst   (route_dst),
169	    .resp_peer  (route_peer),
170	    .resp_bypass(route_bypass)
171	  );
172	
173	  // --------------------------------------------------------------------------
174	  // 3. DATA PLANE LOGIC (Packet Processing FSM)
175	  // --------------------------------------------------------------------------
176	
177	  typedef enum logic [2:0] {S_IDLE, S_COLLECT, S_DECIDE, S_FLUSH, S_FWD} state_e;
178	  state_e state, state_next;
179	
180	  logic [1:0]  beat;          
181	  logic [31:0] ipv4_da;
182	
183	  typedef struct packed {
184	    logic [127:0] data;
185	    logic [15:0]  keep;
186	    logic         last;
187	    logic         valid;
188	  } beat_t;
189	
190	  beat_t beat_buf[0:2];
191	  logic [1:0] buf_rd_ptr;
192	
193	  logic [2:0] decided_dst, decided_dst_n;
194	  logic [7:0] decided_peer, decided_peer_n;
195	  logic       decided_bypass, decided_bypass_n;
196	
197	  logic [1:0] flush_limit, flush_limit_n;
198	
199	  logic in_hs;
200	  assign in_hs = s_axis.tvalid && s_axis.tready;
201	
202	  always_comb begin
203	    unique case (state)
204	      S_IDLE,
205	      S_COLLECT:  s_axis.tready = 1'b1;                
206	      S_DECIDE,
207	      S_FLUSH:    s_axis.tready = 1'b0;                
208	      S_FWD:      s_axis.tready = m_axis.tready;       
209	      default:    s_axis.tready = 1'b0;
210	    endcase
211	  end
212	
213	  always_comb begin
214	    state_next        = state;
215	    decided_dst_n     = decided_dst;
216	    decided_peer_n    = decided_peer;
217	    decided_bypass_n  = decided_bypass;
218	    flush_limit_n     = flush_limit;
219	    route_req_valid   = 1'b0;
220	
221	    case (state)
222	      S_IDLE: begin
223	        if (in_hs) begin
224	          if (s_axis.tuser_bypass_all) begin
225	            decided_dst_n     = s_axis.tuser_dst;
226	            decided_peer_n    = s_axis.tid;
227	            decided_bypass_n  = s_axis.tuser_bypass_stage;
228	            flush_limit_n     = 2'd0;
229	            state_next        = S_FLUSH;
230	          end else begin
231	            state_next        = S_COLLECT;
232	          end
233	        end
234	      end
235	
236	      S_COLLECT: begin
237	        if (in_hs) begin
238	          case (beat)
239	            // Beat 1 corresponds to Beat 2 in waveforms (contains IP:DA3, IP:DA2)
240	            2'd1: begin
241	              ipv4_da[31:24] = s_axis.tdata[119:112]; 
242	              ipv4_da[23:16] = s_axis.tdata[127:120]; 
243	            end
244	
245	            // Beat 2 corresponds to Beat 3 in waveforms (contains IP:DA1, IP:DA0)
246	            2'd2: begin
247	              ipv4_da[15: 8] = s_axis.tdata[  7:  0]; 
248	              ipv4_da[ 7: 0] = s_axis.tdata[ 15:  8]; 
249	              state_next      = S_DECIDE;
250	            end
251	            
252	            default: ;
253	          endcase
254	        end
255	      end
256	
257	      S_DECIDE: begin
258	        route_req_valid   = 1'b1;
259	        decided_dst_n     = route_dst;
260	        decided_peer_n    = route_peer;
261	        decided_bypass_n  = (USE_BYPASS_FROM_MEM) ? route_bypass : s_axis.tuser_bypass_stage;
262	        flush_limit_n     = 2'd2;
263	        state_next        = S_FLUSH;
264	      end
265	
266	      S_FLUSH: begin
267	        if (m_axis.tready && beat_buf[buf_rd_ptr].valid) begin
268	          if (beat_buf[buf_rd_ptr].last) begin
269	            state_next = S_IDLE;
270	          end else if (buf_rd_ptr == flush_limit) begin
271	            state_next = S_FWD;
272	          end
273	        end
274	      end
275	
276	      S_FWD: begin
277	        if (in_hs && s_axis.tlast) begin
278	          state_next = S_IDLE;
279	        end
280	      end
281	
282	      default: begin
283	        state_next = state;
284	      end
285	
286	    endcase
287	  end
288	
289	  always_ff @(posedge s_axis.clk or posedge s_axis.rst) begin
290	    if (s_axis.rst) begin
291	      state <= S_IDLE;
292	      beat  <= 2'd0;
293	      buf_rd_ptr <= 2'd0;
294	      beat_buf[0].valid <= 1'b0; beat_buf[1].valid <= 1'b0; beat_buf[2].valid <= 1'b0;
295	      decided_dst <= 3'd0;
296	      decided_peer<= 8'd0;
297	      decided_bypass <= 1'b0;
298	      route_req_ip <= 32'd0;
299	      flush_limit  <= 2'd0;
300	    end else begin
301	      state <= state_next;
302	      flush_limit <= flush_limit_n;
303	
304	      if (state == S_IDLE) begin
305	        if (in_hs && !s_axis.tuser_bypass_all) beat <= 2'd1;
306	        else                                    beat <= 2'd0;
307	      end else if (state == S_COLLECT && in_hs) begin
308	        beat <= beat + 2'd1; 
309	      end else if (state == S_FWD && in_hs && s_axis.tlast) begin
310	        beat <= 2'd0;
311	      end
312	
313	      if (state == S_IDLE && in_hs) begin
314	         beat_buf[0].data  <= s_axis.tdata;
315	         beat_buf[0].keep  <= s_axis.tkeep;
316	         beat_buf[0].last  <= s_axis.tlast;
317	         beat_buf[0].valid <= 1'b1;
318	      end
319	
320	      if (state == S_COLLECT && in_hs) begin
321	        beat_buf[beat].data  <= s_axis.tdata;
322	        beat_buf[beat].keep  <= s_axis.tkeep;
323	        beat_buf[beat].last  <= s_axis.tlast;
324	        beat_buf[beat].valid <= 1'b1;
325	
326	        if (beat == 2'd1) begin
327	            route_req_ip[31:24] <= s_axis.tdata[119:112];
328	            route_req_ip[23:16] <= s_axis.tdata[127:120];
329	        end
330	        if (beat == 2'd2) begin
331	            route_req_ip[15: 8] <= s_axis.tdata[  7:  0];
332	            route_req_ip[ 7: 0] <= s_axis.tdata[ 15:  8];
333	        end
334	      end
335	      
336	      // (FLUSH)
337	      if (state == S_FLUSH && m_axis.tready && beat_buf[buf_rd_ptr].valid) begin
338	        beat_buf[buf_rd_ptr].valid <= 1'b0;
339	        if (!beat_buf[buf_rd_ptr].last && (buf_rd_ptr < flush_limit)) begin
340	          buf_rd_ptr <= buf_rd_ptr + 2'd1;
341	        end else begin
342	          buf_rd_ptr <= 2'd0; 
343	        end
344	      end
345	
346	      // Buffer reset after IDLE
347	      if (state_next == S_IDLE) begin
348	        beat_buf[0].valid <= 1'b0; beat_buf[1].valid <= 1'b0; beat_buf[2].valid <= 1'b0;
349	        buf_rd_ptr   <= 2'd0;
350	      end
351	
352	      decided_dst    <= decided_dst_n;
353	      decided_peer   <= decided_peer_n;
354	      decided_bypass <= decided_bypass_n;
355	    end
356	  end
357	
358	
359	  logic [127:0] flush_tdata;
360	  logic [15:0]  flush_tkeep;
361	  logic         flush_tlast;
362	  logic         flush_tvalid;
363	
364	  assign flush_tdata  = beat_buf[buf_rd_ptr].data;
365	  assign flush_tkeep  = beat_buf[buf_rd_ptr].keep;
366	  assign flush_tlast  = beat_buf[buf_rd_ptr].last;
367	  assign flush_tvalid = (state == S_FLUSH) && beat_buf[buf_rd_ptr].valid;
368	
369	  assign m_axis.tvalid = (state == S_FLUSH) ? flush_tvalid :
370	                         (state == S_FWD)   ? s_axis.tvalid : 1'b0;
371	  assign m_axis.tdata  = (state == S_FLUSH) ? flush_tdata  :
372	                         (state == S_FWD)   ? s_axis.tdata  : '0;
373	  assign m_axis.tkeep  = (state == S_FLUSH) ? flush_tkeep  :
374	                         (state == S_FWD)   ? s_axis.tkeep  : '0;
375	  assign m_axis.tlast  = (state == S_FLUSH) ? flush_tlast  :
376	                         (state == S_FWD)   ? s_axis.tlast  : 1'b0;
377	
378	  assign m_axis.tuser_bypass_all   = s_axis.tuser_bypass_all;
379	  assign m_axis.tuser_src          = s_axis.tuser_src;
380	  assign m_axis.tuser_bypass_stage = decided_bypass;
381	  assign m_axis.tuser_dst          = decided_dst;
382	  assign m_axis.tid                = decided_peer;
383	
384	endmodule
385	
386	/*
387	-----------------------------------------------------------------------------
388	Version History:
389	-----------------------------------------------------------------------------
390	 2025/12/7 IV: original creation
391	*/
392

